import unittest

from reports.export import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_basic(self):
        result = export_csv(
            [{"a": 1, "b": "x"}, {"a": 2, "b": "y"}],
            ["a", "b"],
        )
        self.assertEqual(result, "a,b\r\n1,x\r\n2,y\r\n")

    def test_quoting(self):
        result = export_csv(
            [{"a": 'he said "hi"', "b": "x,y", "c": "line1\nline2\r\nline3"}],
            ["a", "b", "c"],
        )
        self.assertEqual(
            result,
            'a,b,c\r\n"he said ""hi""","x,y","line1\nline2\r\nline3"\r\n',
        )

    def test_none_missing_and_unselected(self):
        result = export_csv(
            [{"a": None, "b": "keep", "extra": "ignored"}, {"b": "only"}],
            ["a", "b"],
        )
        self.assertEqual(result, "a,b\r\n,keep\r\n,only\r\n")

    def test_non_string_values(self):
        result = export_csv([{"a": 3.5, "b": True}], ["a", "b"])
        self.assertEqual(result, "a,b\r\n3.5,True\r\n")

    def test_unicode(self):
        result = export_csv([{"a": "héllo \U0001f600"}], ["a"])
        self.assertEqual(result, "a\r\nhéllo \U0001f600\r\n")

    def test_generators(self):
        result = export_csv(
            iter([{"a": 1}, {"a": 2}]),
            iter(["a"]),
        )
        self.assertEqual(result, "a\r\n1\r\n2\r\n")

    def test_empty_rows(self):
        self.assertEqual(export_csv([], ["a", "b"]), "a,b\r\n")

    def test_empty_columns(self):
        self.assertEqual(export_csv([{"a": 1}], []), "\r\n\r\n")

    def test_rejects_duplicates(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])

    def test_rejects_non_string_columns(self):
        with self.assertRaises(ValueError):
            export_csv([], [1])

    def test_does_not_mutate_inputs(self):
        rows = [{"a": 1}]
        columns = ["a"]
        export_csv(rows, columns)
        self.assertEqual(rows, [{"a": 1}])
        self.assertEqual(columns, ["a"])


if __name__ == "__main__":
    unittest.main()

