def _quote_field(value):
    """Format one CSV field with RFC 4180 minimal quoting and quote doubling."""
    if value is None:
        return ""
    text = value if isinstance(value, str) else str(value)
    if any(ch in text for ch in (",", '"', "\r", "\n")):
        return '"' + text.replace('"', '""') + '"'
    return text


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header.

    rows: iterable of mappings.
    columns: ordered iterable of unique string column names.

    Raises ValueError for duplicate or non-string column names.
    """
    columns = list(columns)
    for name in columns:
        if not isinstance(name, str):
            raise ValueError("column names must be strings: %r" % (name,))
    if len(set(columns)) != len(columns):
        raise ValueError("duplicate column names are not allowed")

    lines = [",".join(_quote_field(name) for name in columns)]
    if columns:
        for row in rows:
            lines.append(
                ",".join(_quote_field(row.get(name)) for name in columns)
            )
    return "\r\n".join(lines) + "\r\n"

